    }
    if (hdrchkRange(dl_max, dl)) {
        rasprintf(emsg, _("hdr data: BAD, no. of bytes(%" PRIu32 ") out of range"), dl);
        return RPMRC_FAIL;
    }
    return RPMRC_OK;
}

