    final int length = value.length;
    boolean needsEncoding = false;
    for (int i = 0; i < length; i++) {
        if (!allowedChars.get(value.data[i] & 0xFF)) {
            needsEncoding = true;
            break;
        }
    }
    if (!needsEncoding) {
        return new String(value.data, 0, 0, length);
