def _verify(self, M, sig):
    if sig[0]<1 or sig[0]>p-1:
        return 0
    v1=pow(self.y, sig[0], self.p)
    v1=(v1*pow(sig[0], sig[1], self.p)) % self.p
    v2=pow(self.g, M, self.p)
    if v1==v2:
        return 1
    return 0

