    regex = re.compile(r'^(?:(?:[\w\-#_= /:]*|[+]|[!])(\(?P<\w+>.+\)))+$')
    error_msg = _('Invalid linkifier pattern.  Valid characters are {}.').format(
        '[ a-zA-Z_#=/:+!-]',
    )
