def safe_unpack_archive(archive_path, destination_dir):
    with tarfile.open(archive_path, 'r:*') as tar:
        for member in tar.getmembers():
            member_path = os.path.join(destination_dir, member.name)
            if not os.path.abspath(member_path).startswith(os.path.abspath(destination_dir)):
                raise ValueError('Attempted Path Traversal in Tar File')
        tar.extractall(destination_dir)

