    if (num_args <= 0 || num_args > MAX_SAFE_SIZE) {
        return NULL;
    }

    size_t allocation_size = num_args * sizeof(int);
    if (allocation_size / sizeof(int) != num_args) {
        return NULL; // Overflow detected
    }

    int* reversed_args = (int*)malloc(allocation_size);
    if (reversed_args == NULL) {
        return NULL;
    }

    va_list args;
    va_start(args, num_args);

    for (int i = 0; i < num_args; i++) {
