using System.Text.RegularExpressions;

namespace SecureApp
{
    public class ProcessRunner
    {
        public static void RunProcess(string executable, string args)
        {
            if (!IsValidExecutable(executable))
            {
                throw new ArgumentException("Invalid executable path.");
            }

            if (!IsValidArguments(args))
            {
                throw new ArgumentException("Invalid arguments.");
            }

            Process proc = new Process();
            proc.StartInfo.FileName = executable;
            proc.StartInfo.Arguments = args;
            proc.Start();
        }

        private static bool IsValidExecutable(string path)
        {
            return Regex.IsMatch(path, @"^[a-zA-Z0-9\\\/.:_-]+$");
        }

        private static bool IsValidArguments(string args)
        {
            return !args.Contains(";") && !args.Contains("&") && !args.Contains("|");
        }
    }
}

