fixing_example:
function scheduleCallback(callback, win) {
    win = win || window;
    const sentinelValue = 'zero-timeout-message';
    const targetOrigin = 'https://trusted-origin.com';
    win.postMessage(sentinelValue, targetOrigin);

    function messageHandler(e) {
        if (e.origin !== targetOrigin) return;
        if (e.data === sentinelValue) {
            if (callback && typeof callback === 'function') {
                callback();
            }
        }
    }

    if (win.addEventListener) {
        win.addEventListener('message', messageHandler);
    } else if (win.attachEvent) {
        win.attachEvent('onmessage', messageHandler);
    } else {
        throw new Error('Event listener not supported');
    }
}

