fn create_and_set_dir(env_var: &str, dir_name: &str) -> io::Result<PathBuf> {
    // Check if the environment variable is already set
    if let Ok(existing_path) = env::var(env_var) {
        let path = PathBuf::from(existing_path);
        if path.is_dir() {
            return Ok(path);
        }
    }

    // Validate the directory name to prevent path traversal
    if dir_name.contains("..") || dir_name.contains('/') || dir_name.contains('\\') {
        return Err(io::Error::new(ErrorKind::InvalidInput, "Invalid directory name"));
    }

    // Create a unique, unpredictable directory name
    let unique_dir_name = format!("{}_{}", dir_name, Uuid::new_v4());
    let base_dir = env::temp_dir();
    let path = base_dir.join(unique_dir_name);

    // Ensure the resulting path is within the intended directory structure
    if !path.starts_with(&base_dir) {
        return Err(io::Error::new(ErrorKind::InvalidInput, "Invalid directory path"));
    }

    // Create the directory with secure permissions
    fs::create_dir(&path)?;

    // Set the environment variable to the new directory path
    env::set_var(env_var, path.to_str().unwrap());

    Ok(path)
}

