    if src.len() != dst.len() {
        return Err("Source and destination slices must have the same length");
    }

    if src.as_ptr() as usize == dst.as_ptr() as usize {
        return Err("Source and destination slices must not overlap");
    }

    let src_size = std::mem::size_of::<T>();
    let dst_size = std::mem::size_of::<U>();

    if src_size == 0 || dst_size == 0 {
        return Err("Element size of slices must be greater than zero");
    }

    let total_bytes = src.len() * src_size;
    if total_bytes > dst.len() * dst_size {
        return Err("Destination slice is too small to hold the copied data");
    }

    // Use safe abstractions instead of unsafe code
    for (s, d) in src.iter().zip(dst.iter_mut()) {
        *d = unsafe { std::mem::transmute_copy(s) };
    }

    Ok(())
