    let status = unsafe { hsa_queue_create(agent, size, queue_type, None, None, u32::MAX, u32::MAX, &mut queue) };

    if status != hsa_status_t::HSA_STATUS_SUCCESS {
        return Err(QueueError::QueueCreationFailed(status));
    }

    Ok(queue)
