use std::env;
use std::process::Command;
use std::path::Path;

fn open_docs(path: &Path) -> Result<String, Vec<String>> {
    let mut methods = Vec::new();

    if let Ok(name) = env::var("BROWSER") {
        if !name.is_empty() && name.chars().all(|c| c.is_alphabetic()) {
            match Command::new(&name).arg(path).status() {
                Ok(_) => return Ok(name),
                Err(_) => methods.push(name),
            }
        }
    }

    for m in ["xdg-open", "gnome-open", "kde-open"].iter() {
        match Command::new(m).arg(path).status() {
            Ok(_) => return Ok(m.to_string()),
            Err(_) => methods.push(m.to_string()),
        }
    }

    Err(methods)
}
